<?php
namespace App\Http\Controllers; use App\Http\Requests\StoreTrainingQuestionRequest; use App\Models\{TrainingQuestion,TrainingTopic}; use App\Services\TrainingQuestionService;
class TrainingQuestionController extends Controller{public function index(){ $company=auth()->user()->company_id;$topics=TrainingTopic::availableTo($company)->get();$questions=TrainingQuestion::forCompany($company)->with(['topic','options'])->get();return view('training.questions.index',compact('topics','questions'));}public function store(StoreTrainingQuestionRequest$r,TrainingQuestionService$s){$s->create($r->validated(),$r->user()->company_id,$r->user()->id);return back()->with('success','Pregunta creada.');}}
